import * as Tone from 'tone';
import { dbDelete, dbGetAll, dbPut, dbGet } from '../storage/db';
import { isDrumVoice, renderDrumVoice } from '../instruments/drumSynthesis';
import { getPackOneShot } from './samplePacks';

/**
 * Sample ids:
 *  - `voice:<drumVoiceId>` — factory sound generated by synthesis
 *  - `user:<uuid>`         — audio imported by the user (stored in IndexedDB)
 *  - `pack:<pack>/<zone>`  — a one-shot from a sampled pack (e.g. percussion)
 */

export interface UserSampleRecord {
  id: string;
  name: string;
  category: string;
  tags: string[];
  createdAt: number;
  size: number;
  type: string;
  blob: Blob;
}

export type UserSampleMeta = Omit<UserSampleRecord, 'blob'>;

const bufferCache = new Map<string, Promise<AudioBuffer>>();

async function decode(blob: Blob): Promise<AudioBuffer> {
  const data = await blob.arrayBuffer();
  // Decoding on the raw context works for both live and offline rendering:
  // AudioBuffers are not tied to the context that decoded them.
  return Tone.getContext().rawContext.decodeAudioData(data);
}

export function getSampleBuffer(sampleId: string): Promise<AudioBuffer> {
  const hit = bufferCache.get(sampleId);
  if (hit) return hit;
  let p: Promise<AudioBuffer>;
  if (sampleId.startsWith('voice:')) {
    const v = sampleId.slice(6);
    if (!isDrumVoice(v)) return Promise.reject(new Error(`Unknown voice ${v}`));
    p = renderDrumVoice(v);
  } else if (sampleId.startsWith('user:')) {
    p = dbGet<UserSampleRecord>('samples', sampleId).then((rec) => {
      if (!rec) throw new Error(`Sample ${sampleId} not found`);
      return decode(rec.blob);
    });
  } else if (sampleId.startsWith('pack:')) {
    p = getPackOneShot(sampleId.slice(5));
  } else {
    return Promise.reject(new Error(`Unknown sample id ${sampleId}`));
  }
  p.catch(() => bufferCache.delete(sampleId));
  bufferCache.set(sampleId, p);
  return p;
}

const MAX_IMPORT_BYTES = 50 * 1024 * 1024;

export async function importUserSample(file: File, category = 'Imported'): Promise<UserSampleMeta> {
  if (file.size > MAX_IMPORT_BYTES) throw new Error('File too large (max 50 MB)');
  // Validate that the browser can decode it before storing.
  await decode(file);
  const rec: UserSampleRecord = {
    id: `user:${crypto.randomUUID()}`,
    name: file.name.replace(/\.[a-z0-9]+$/i, ''),
    category,
    tags: [],
    createdAt: Date.now(),
    size: file.size,
    type: file.type || 'audio/*',
    blob: file,
  };
  await dbPut('samples', rec);
  const { blob: _blob, ...meta } = rec;
  void _blob;
  return meta;
}

export async function listUserSamples(): Promise<UserSampleMeta[]> {
  const all = await dbGetAll<UserSampleRecord>('samples');
  return all
    .map(({ blob: _b, ...meta }) => meta)
    .sort((a, b) => b.createdAt - a.createdAt);
}

export async function deleteUserSample(id: string): Promise<void> {
  bufferCache.delete(id);
  await dbDelete('samples', id);
}

// ----------------------------------------------------------- preview player

let previewSource: Tone.ToneBufferSource | null = null;
let previewOut: Tone.Gain | null = null;

export async function previewSample(sampleId: string): Promise<void> {
  await Tone.start();
  const buf = await getSampleBuffer(sampleId);
  stopPreview();
  if (!previewOut) previewOut = new Tone.Gain(0.8).toDestination();
  previewSource = new Tone.ToneBufferSource(new Tone.ToneAudioBuffer(buf)).connect(previewOut);
  previewSource.start();
}

export function stopPreview(): void {
  if (previewSource) {
    try {
      previewSource.stop();
    } catch {
      /* already stopped */
    }
    previewSource = null;
  }
}
